import math
def control(obs):
    cam=obs.get('views',{}).get('camera')
    h=obs['hitch_deg']
    if not cam: return (1.8*h,-0.5,-23)
    th=math.radians(obs['rig']['trailer_heading_deg'])
    rear=obs['rig']['trailer_rear']
    pts=[]
    for b,d in cam.get('walls',[]):
        a=math.radians(b); x=cam['origin'][0]+d*math.cos(a)-rear[0]; y=cam['origin'][1]+d*math.sin(a)-rear[1]
        u=-x*math.cos(th)-y*math.sin(th); z=-x*math.sin(th)+y*math.cos(th)
        if u>0.3: pts.append((u,z))
    centers=[]
    for dist in (2.5,3.5,4.5):
        sides=[]
        for sign in (-1,1):
            p=sorted([(abs(u-dist),u,z) for u,z in pts if z*sign>0],key=lambda p:p[0])[:2]
            if p and p[0][0]<1.6:
                weights=[1/(0.12+q[0]**2) for q in p]
                sides.append(sum(q[2]*w for q,w in zip(p,weights))/sum(weights))
        if len(sides)==2: centers.append((dist,sum(sides)/2))
    if centers:
        angle=sum(math.degrees(math.atan2(z,u)) for u,z in centers)/len(centers)
        steer=2.0*h-3.0*angle
    else: steer=1.8*h
    return (max(-32,min(32,steer)),-0.65,-23)

