import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    if not cam: return (max(-32,min(32,2*h)),-0.4,-23)
    th=math.radians(obs['rig']['trailer_heading_deg'])
    rear=obs['rig']['trailer_rear']
    def convert(p):
        b,d=p; a=math.radians(b)
        x=cam['origin'][0]+d*math.cos(a)-rear[0]
        y=cam['origin'][1]+d*math.sin(a)-rear[1]
        return (-x*math.cos(th)-y*math.sin(th),-x*math.sin(th)+y*math.cos(th))
    corners=sorted(convert(p) for p in cam.get('target_corners',[]))
    angle=0
    if len(corners)==4:
        near=[sum(p[i] for p in corners[:2])/2 for i in (0,1)]
        far=[sum(p[i] for p in corners[2:])/2 for i in (0,1)]
        slope=(far[1]-near[1])/max(1,far[0]-near[0])
        u=3.0
        z=near[1]+slope*(u-near[0])
        angle=math.degrees(math.atan2(z,u))
    else:
        pts=[convert(p) for p in cam.get('walls',[])]
        sides=[]
        for sign in (-1,1):
            p=sorted((abs(u-3),z) for u,z in pts if u>0.3 and z*sign>0)[:2]
            if p and p[0][0]<1.6:
                sides.append(sum(z/(0.12+d*d) for d,z in p)/sum(1/(0.12+d*d) for d,z in p))
        if len(sides)==2: angle=math.degrees(math.atan2(sum(sides)/2,3))
    steer=2*h-3*angle
    return (max(-32,min(32,steer)),-0.45,-23)

